        "kind": "code",
        "source": "def solve_transport(supply, demand, cost):\n    model = Model(\"IE-OPT-07 box transport\")\n    model.hideOutput(True)\n    x = {(i, j): model.addVar(vtype=\"I\", lb=0, name=f\"ship_{i}_{j}\")\n         for i in range(len(supply)) for j in range(len(demand))}\n    for i in range(len(supply)):\n        model.addCons(quicksum(x[i, j] for j in range(len(demand))) == supply[i])\n    for j in range(len(demand)):\n        model.addCons(quicksum(x[i, j] for i in range(len(supply))) == demand[j])\n    model.setObjective(quicksum(cost[i][j] * x[i, j]\n                                 for i in range(len(supply))\n                                 for j in range(len(demand))), \"minimize\")\n    model.optimize()\n    status = str(model.getStatus())\n    if status != \"optimal\":\n        raise RuntimeError(f\"Solver status is {status}; optimality not certified\")\n    shipments = [[int(round(model.getVal(x[i, j]))) for j in range(len(demand))]\n                 for i in range(len(supply))]\n    return {\"objective\": float(model.getObjVal()), \"shipments\": shipments}\n\nresult = solve_transport(supply, demand, cost)\nprint(\"最小运费:\", result[\"objective\"])\nfor i, name in enumerate(warehouses):\n    sent = {stores[j]: result[\"shipments\"][i][j] for j in range(len(stores))}\n    print(name, sent)"
