        "kind": "code",
        "source": "def solve_tsp(travel):\n    n = len(travel)\n    model = Model(\"IE-OPT-09 tsp mtz\")\n    model.hideOutput(True)\n    x = {(i, j): model.addVar(vtype=\"B\", name=f\"go_{i}_{j}\")\n         for i in range(n) for j in range(n) if i != j}\n    u = {i: model.addVar(lb=1, ub=n - 1, vtype=\"C\", name=f\"order_{i}\") for i in range(1, n)}\n    model.setObjective(quicksum(travel[i][j] * x[i, j] for i, j in x), \"minimize\")\n    for i in range(n):\n        model.addCons(quicksum(x[i, j] for j in range(n) if j != i) == 1)\n        model.addCons(quicksum(x[j, i] for j in range(n) if j != i) == 1)\n    for i in range(1, n):\n        for j in range(1, n):\n            if i != j:\n                model.addCons(u[i] - u[j] + n * x[i, j] <= n - 1)\n    model.optimize()\n    status = str(model.getStatus())\n    if status != \"optimal\":\n        raise RuntimeError(f\"Solver status is {status}; optimality not certified\")\n    nxt = {i: next(j for j in range(n) if j != i and model.getVal(x[i, j]) > 0.5)\n           for i in range(n)}\n    tour = [0]\n    while len(tour) <= n:\n        tour.append(nxt[tour[-1]])\n        if tour[-1] == 0:\n            break\n    return {\"objective\": float(model.getObjVal()), \"tour\": tour}\n\nresult = solve_tsp(travel)\nprint(\"最短总车程:\", round(result[\"objective\"]))\nprint(\"巡检顺序:\", \" → \".join(places[i] for i in result[\"tour\"]))"
